-- Seven new, reviewed Dutch editions; all-or-nothing, identity-bound, no schema changes.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
DO $operation$
DECLARE r jsonb; eid bigint;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($records$[{"id":208,"ol":"OL35623W","authorId":127,"author":"Octavia E. Butler","title":"De zaaier","isbn":"9789056727116","publisher":"Signatuur","format":"paperback","sourceType":"official_publisher","sourceName":"Signatuur / A.W. Bruna","sourceUrl":"https://www.awbruna.nl/boek/romans/octavia-butler/de-zaaier/","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.439061253.html/de-zaaier/","description":"Lauren Olamina groeit op in een ommuurde gemeenschap in Californië. Buiten de muren raken mensen door armoede, geweld en klimaatverandering steeds verder op drift. Lauren voelt bovendien de pijn van anderen alsof het haar eigen pijn is. Wanneer haar vertrouwde omgeving wegvalt, moet ze op zoek naar veiligheid en mensen op wie ze kan bouwen. De zaaier verbindt een overlevingstocht met vragen over geloof, verandering en de mogelijkheid om samen een nieuwe gemeenschap te vormen.","angle":"Klimaat, overleven en een nieuwe gemeenschap","note":"Lauren moet haar weg vinden door een ontwricht Californië en zoekt onderweg naar vertrouwen en houvast. Kies De zaaier als je een dystopie wilt waarin klimaat, ongelijkheid en het opbouwen van een gemeenschap samenkomen. Het overlevingsverhaal stelt ook de vraag welke ideeën mensen bij elkaar kunnen houden wanneer bestaande zekerheden verdwijnen.","cover":"https://www.awbruna.nl/wp-content/uploads/sites/51/external/19c506902c71016720bde524882f5572-364x0-c-default.png?t=1794481285","coverSource":"https://www.awbruna.nl/boek/romans/octavia-butler/de-zaaier/"},{"id":2600,"ol":"OL675722W","authorId":8,"author":"Margaret Atwood","title":"Oryx en Crake","isbn":"9789035125414","publisher":"Bert Bakker","format":"paperback","sourceType":"official_catalog","sourceName":"Rozet bibliotheek","sourceUrl":"https://rozet.nl/catalogus/1941478/","supportingUrl":"https://www.deslegte.com/oryx-en-crake-119403/","description":"In een verwoeste wereld probeert Sneeuwman te overleven tussen wezens die op mensen lijken, maar op beslissende punten anders zijn. Zijn herinneringen voeren terug naar Oryx en zijn vriend Crake, en naar een samenleving waarin bedrijven en genetische experimenten vergaande invloed hadden. Langzaam wordt duidelijk hoe die vroegere wereld samenhangt met zijn eenzame bestaan. Oryx en Crake onderzoekt de grenzen van maakbaarheid, de gevolgen van commerciële wetenschap en de kwetsbaarheid van menselijke relaties. Het is het eerste deel van de MaddAddam-trilogie.","angle":"Genetische techniek en de maakbare mens","note":"Sneeuwman kijkt vanuit een ontwrichte wereld terug op zijn band met Oryx en Crake. Deze roman past bij lezers die willen nadenken over genetische techniek, bedrijvenmacht en de gevolgen van vooruitgang zonder grenzen. Begin hier als je de MaddAddam-trilogie in publicatievolgorde wilt lezen; Het jaar van de vloed belicht daarna andere ervaringen in dezelfde wereld.","cover":"https://www.deslegte.com/images/cached/resample/webp/data/uploads/389/600/cms_visual_1685864.jpg_1634905037000_389x600_0.8_p-b5db1149c3.webp","coverSource":"https://www.deslegte.com/oryx-en-crake-119403/"},{"id":100,"ol":"OL1846076W","authorId":87,"author":"Lois Lowry","title":"The Giver: bewaker van herinneringen","isbn":"9789401417471","publisher":"Lannoo","format":"paperback","sourceType":"official_publisher","sourceName":"Lannoo — Nederlands inkijkexemplaar","sourceUrl":"https://www.de-leukste-kinderboeken.com/sites/default/files/books/issuu/9789401419444.pdf","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.390773174.html/the-giver/","description":"Jonas leeft in een gemeenschap waarin bijna alles voor de inwoners wordt geregeld. Conflicten en onzekerheid lijken verdwenen, maar ruimte voor eigen keuzes is er nauwelijks. Wanneer hij wordt aangewezen als bewaker van herinneringen, krijgt hij toegang tot ervaringen die de andere bewoners niet kennen. Wat hij leert, verandert zijn kijk op de schijnbare veiligheid van zijn wereld. The Giver: bewaker van herinneringen gaat over de waarde van gevoelens, herinneringen en vrijheid. Deze editie is de Nederlandse vertaling door Laure van den Broeck.","angle":"Wat kost een leven zonder pijn?","note":"Jonas ontdekt als bewaker van herinneringen wat zijn zorgvuldig geregelde gemeenschap heeft opgegeven. Kies dit boek als je maatschappelijke controle via een helder, persoonlijk verhaal wilt verkennen. Naast Laat me nooit alleen biedt het een andere invalshoek op herinneringen en keuzevrijheid. Ondanks de Engelse hoofdtitel is deze editie Nederlandstalig.","cover":"https://www.deslegte.com/images/cached/resample/webp/data/uploads/400/600/cms_visual_196592.jpg_1429070632000_400x600_0.8_p-6e6cccb80a.webp","coverSource":"https://www.deslegte.com/the-giver-434059/"},{"id":2717,"ol":"OL17876096W","authorId":1307,"author":"Neal Shusterman","title":"Zeis","isbn":"9789059248427","publisher":"Baeckens","format":"hardcover","sourceType":"official_catalog","sourceName":"Rozet bibliotheek","sourceUrl":"https://rozet.nl/catalogus/2037737/","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.434228923.html/zeis/","description":"In de wereld van Citra en Rowan zijn ziekte, honger en oorlog overwonnen. Mensen sterven niet meer vanzelf, waardoor een kleine groep Zeisen beslist wie moet sterven om de bevolking te begrenzen. De twee tieners worden opgeleid voor dat werk, hoewel geen van beiden het ambieert. Hun opleiding confronteert hen met macht, verantwoordelijkheid en botsende opvattingen over rechtvaardigheid. Zeis laat zien hoe een samenleving die alle grote problemen lijkt te hebben opgelost nieuwe morele dilemma’s kan creëren. Het is het eerste boek van de reeks.","angle":"Een perfecte wereld met onmogelijke keuzes","note":"Citra en Rowan worden opgeleid voor een taak die niemand graag op zich neemt: bepalen wie sterft in een wereld zonder natuurlijke dood. Zeis past bij lezers die spanning willen combineren met ethische dilemma’s. De vraag wie over een ander leven mag beslissen verbindt het boek met Gesplitst, maar het vertrekpunt is een ogenschijnlijk ideale samenleving.","cover":"https://www.deslegte.com/images/cached/resample/webp/data/uploads/377/600/cms_visual_1670785.jpg_1632447533000_377x600_0.8_p-20559358f2.webp","coverSource":"https://www.deslegte.com/zeis-2803995/"},{"id":179,"ol":"OL15719630W","authorId":135,"author":"Veronica Roth","title":"Divergent 1 - Inwijding","isbn":"9789000407392","publisher":"Van Goor","format":"paperback","sourceType":"official_publisher","sourceName":"Van Goor / Lannoo","sourceUrl":"https://www.lannoo.com/nl-nl/young-adult/divergent-1-inwijding-9789000407392","supportingUrl":"https://www.deslegte.com/divergent-1-inwijding-5530095/","description":"In het toekomstige Chicago hoort iedereen bij een van vijf facties, elk gebouwd rond een bepaalde deugd. De zestienjarige Beatrice Prior moet kiezen waar zij voortaan bij wil horen. Haar keuze stelt de band met haar familie op de proef en brengt haar in een veeleisende inwijding. Terwijl ze zichzelf als Tris opnieuw leert kennen, ontdekt ze hoe moeilijk het is om in één vast kader te passen. Inwijding opent de Divergent-reeks met vragen over identiteit, loyaliteit en een samenleving die mensen naar eigenschappen indeelt.","angle":"Identiteit, groepsdruk en verzet","note":"Beatrice moet kiezen tussen vijf facties en ontdekt dat een mens niet vanzelf in één voorgeschreven hokje past. Kies Inwijding als je na De Hongerspelen verder wilt met een jonge hoofdpersoon, een veeleisende selectie en een samenleving vol grenzen. Dit is het eerste deel van Divergent; de strijd om zelf te bepalen wie je bent staat centraal.","cover":"https://www.deslegte.com/images/cached/resample/webp/data/uploads/392/600/cms_visual_4880634.jpg_1776837976000_392x600_0.8_p-23714d653f.webp","coverSource":"https://www.deslegte.com/divergent-1-inwijding-5530095/"},{"id":2724,"ol":"OL1954412W","authorId":1307,"author":"Neal Shusterman","title":"Gesplitst","isbn":"9789047704010","publisher":"Lemniscaat","format":"paperback","sourceType":"official_catalog","sourceName":"Rozet bibliotheek","sourceUrl":"https://rozet.nl/catalogus/1045775/","supportingUrl":"https://lt-tijdschriften.nl/ojs/index.php/ltm/article/download/161/156/315","description":"Connor, Risa en Lev groeien op in een samenleving die een gruwelijk compromis over het recht op leven heeft gesloten. Tieners kunnen worden gesplitst: hun lichaamsdelen gaan naar anderen, zodat de overheid volhoudt dat hun leven voortduurt. De drie jongeren hebben verschillende achtergronden, maar lopen tegen hetzelfde systeem aan. Tijdens hun vlucht raken hun levens met elkaar verbonden. Gesplitst, de Nederlandse vertaling van Unwind, is een indringend toekomstverhaal over lichamelijke autonomie, de macht van volwassenen en het recht om over je eigen bestaan te beslissen.","angle":"Lichamelijke autonomie en een vlucht voor het systeem","note":"Drie jongeren worden bedreigd door een systeem dat hun lichaam als een verzameling herbruikbare delen beschouwt. Gesplitst is een indringende keuze als je de spanning van een vluchtverhaal wilt verbinden met vragen over rechten en autonomie. Vergeleken met Zeis staat hier vooral centraal hoe jongeren proberen te ontkomen aan besluiten die anderen over hen nemen.","cover":"https://media.s-bol.com/BXYKDGm42pXW/2DQqOj/550x826.jpg","coverSource":"https://www.bol.com/nl/nl/p/gesplitst/1001004011522961/"},{"id":2846,"ol":"OL675774W","authorId":8,"author":"Margaret Atwood","title":"Het jaar van de vloed","isbn":"9789044613988","publisher":"Prometheus","format":"paperback","editionOl":"OL47219192M","sourceType":"official_catalog","sourceName":"Rozet bibliotheek","sourceUrl":"https://rozet.nl/catalogus/1456593/","supportingUrl":"https://www.deslegte.com/het-jaar-van-de-vloed-385974/","description":"Een ramp heeft de mensheid vrijwel weggevaagd. Twee vrouwen die verbonden waren met een religieuze gemeenschap proberen te overleven en kijken terug op de wereld die eraan voorafging. Daar botsten zorg voor de natuur, wetenschap en geloof met de macht van bedrijven en alledaags geweld. Het jaar van de vloed laat dezelfde ontwrichte wereld als Oryx en Crake vanuit andere levens zien. Als tweede deel van de MaddAddam-trilogie verdiept het de vragen over verantwoordelijkheid voor elkaar en voor de omgeving waarin mensen proberen voort te bestaan.","angle":"Ecologie, geloof en overleven aan de rand","note":"Twee vrouwen ervaren de wereld van MaddAddam vanuit een andere positie dan de hoofdpersonen van Oryx en Crake. Kies Het jaar van de vloed voor de verbinding tussen ecologie, geloof en overleven. Het verhaal vult de gebeurtenissen van het eerdere boek aan; onze leesroute is eerst Oryx en Crake, daarna dit tweede deel.","cover":"https://www.deslegte.com/images/cached/resample/webp/data/uploads/372/600/cms_visual_157927.jpg_1420780252000_372x600_0.8_p-707b2ea1a1.webp","coverSource":"https://www.deslegte.com/het-jaar-van-de-vloed-385974/"}]$records$::jsonb) LOOP
    PERFORM 1 FROM public.works WHERE id=(r->>'id')::bigint AND author_id=(r->>'authorId')::bigint AND open_library_id=r->>'ol' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work identity changed: %',r->>'id'; END IF;
    IF EXISTS(SELECT 1 FROM public.editions WHERE isbn_13=r->>'isbn' OR (work_id=(r->>'id')::bigint AND language IN('nl','nld','dut'))) THEN RAISE EXCEPTION 'Dutch edition or ISBN already exists: %',r->>'id'; END IF;
    IF EXISTS(SELECT 1 FROM public.catalog_work_descriptions WHERE work_id=(r->>'id')::bigint AND language='nl') THEN RAISE EXCEPTION 'Dutch description already exists: %',r->>'id'; END IF;
    INSERT INTO public.editions(work_id,open_library_edition_id,isbn_13,language,publisher,title) VALUES((r->>'id')::bigint,r->>'editionOl',r->>'isbn','nld',r->>'publisher',r->>'title') RETURNING id INTO eid;
    INSERT INTO public.catalog_work_descriptions(work_id,language,bound_author_id,text,source_type,source_name,source_url,evidence,provenance,review_status,reviewed_at,review_batch) VALUES((r->>'id')::bigint,'nl',(r->>'authorId')::bigint,r->>'description',r->>'sourceType',r->>'sourceName',r->>'sourceUrl',jsonb_build_array(jsonb_build_object('url',r->>'sourceUrl','checkedOn','2026-11-16','purpose','Plot and work identity; original editorial summary'),jsonb_build_object('url',r->>'supportingUrl','checkedOn','2026-11-16','purpose','Edition and translation corroboration')),'original_source_reviewed_summary','approved',now(),'nl-dystopia-complete-20261116');
    INSERT INTO public.catalog_edition_metadata(edition_id,work_id,bound_author_id,bound_title,bound_language,bound_isbn13,format,cover_url,card_cover_url,evidence_url,evidence,review_status,reviewed_at,review_batch) VALUES(eid,(r->>'id')::bigint,(r->>'authorId')::bigint,r->>'title','nld',r->>'isbn',r->>'format',r->>'cover',r->>'cover',r->>'coverSource',jsonb_build_array(jsonb_build_object('url',r->>'coverSource','isbn13',r->>'isbn','checkedOn','2026-11-16','purpose','Standalone Dutch edition, exact ISBN and visually checked cover'),jsonb_build_object('url',r->>'supportingUrl','checkedOn','2026-11-16','purpose','Bibliographic corroboration')),'approved',now(),'nl-dystopia-complete-20261116');
  END LOOP;
  -- Original publication: HarperCollins 2011, confirmed by the publisher colophon
  -- https://content.penguinrandomhouse.de/content/edition/excerpts/1030040.pdf
  UPDATE public.works SET first_publish_year=2011 WHERE id=179 AND open_library_id='OL15719630W' AND author_id=135 AND first_publish_year=2010;
  IF NOT FOUND THEN RAISE EXCEPTION 'Divergent publication year changed'; END IF;
END $operation$;
SELECT m.work_id,m.edition_id,m.bound_title,m.bound_isbn13,m.review_batch FROM public.catalog_edition_metadata m WHERE review_batch='nl-dystopia-complete-20261116' ORDER BY work_id;
COMMIT;
